module float_multi (
	input clk,
	input rst,
	input [31:0] a,
	input [31:0] b,
	output reg [31:0] z
);
	reg [2:0] counter;
	reg [23:0] a_mantissa, b_mantissa, z_mantissa;
	reg [9:0] a_exponent, b_exponent, z_exponent;
	reg a_sign, b_sign, z_sign;
	reg [49:0] product;
	reg guard_bit, round_bit, sticky;

	// Sequential block for initialization
	always @(posedge clk or posedge rst) begin
		if (rst) 
			counter <= 3'b000;
		else
			counter <= counter + 1;
	end
	// Sequential block for extracting fields and processing
	always @(posedge clk) begin
		case(counter)
			3'b000: begin
				a_mantissa <= {1'b1, a[22:0]};
				b_mantissa <= {1'b1, b[22:0]};
				a_exponent <= a[30:23];
				b_exponent <= b[30:23];
				a_sign <= a[31];
				b_sign <= b[31];
			end

			3'b001: begin
				product <= a_mantissa * b_mantissa;
				guard_bit <= product[22];
				round_bit <= product[21];
				sticky <= |product[20:0];
				z_mantissa <= product[49:26] + (guard_bit & (round_bit | sticky));

				if(z_mantissa[23])
					begin
						z_exponent <= a_exponent + b_exponent - 127 + 1;
						z_mantissa <= z_mantissa >> 1;
					end
				else
					begin
						z_exponent <= a_exponent + b_exponent - 127;
					end

				if ((a_exponent == 255 && a_mantissa != 0) || (b_exponent == 255 && b_mantissa != 0))
					begin
						z_exponent <= 255;
						z_mantissa <= 0;
						z_sign <= a_sign ^ b_sign;
					end
				else if (a_exponent == 255 || b_exponent == 255)
					begin
						z_exponent <= 255;
						z_mantissa <= 0;
						z_sign <= a_sign ^ b_sign;
					end
				else if (z_exponent >= 255)
					begin
						z_exponent <= 255;
						z_mantissa <= 0;
						z_sign <= a_sign ^ b_sign;
					end
				else if (z_exponent <= 0)
					begin
						z_exponent <= 0;
						z_mantissa <= 0;
						z_sign <= a_sign ^ b_sign;
					end
				else
					begin
						z_sign <= a_sign ^ b_sign;
					end

			end

			default: z <= {z_sign, z_exponent, z_mantissa};

		endcase
	end

endmodule
